import React, { useMemo, useState } from 'react';
import {
  JxChip,
  JxCircularProgress,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over-quota' | 'completed';

interface Project {
  id: string;
  name: string;
  status: ProjectStatus;
  quotaPercent: number;
}

const PROJECTS: Project[] = [
  { id: 'p-01', name: 'Атлас логистики', status: 'active', quotaPercent: 62 },
  { id: 'p-02', name: 'Портал самообслуживания', status: 'over-quota', quotaPercent: 118 },
  { id: 'p-03', name: 'Аналитика продаж', status: 'active', quotaPercent: 41 },
  { id: 'p-04', name: 'Миграция биллинга', status: 'paused', quotaPercent: 30 },
  { id: 'p-05', name: 'Мобильный клиент', status: 'active', quotaPercent: 87 },
  { id: 'p-06', name: 'Архив документов', status: 'completed', quotaPercent: 100 },
  { id: 'p-07', name: 'Служба поддержки', status: 'over-quota', quotaPercent: 104 },
  { id: 'p-08', name: 'Каталог поставщиков', status: 'paused', quotaPercent: 15 },
  { id: 'p-09', name: 'Панель метрик', status: 'active', quotaPercent: 73 },
  { id: 'p-10', name: 'Онбординг клиентов', status: 'completed', quotaPercent: 100 },
  { id: 'p-11', name: 'Резервное хранилище', status: 'over-quota', quotaPercent: 132 },
  { id: 'p-12', name: 'Интеграция с CRM', status: 'active', quotaPercent: 55 },
];

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'Приостановлен',
  'over-quota': 'Превышена квота',
  completed: 'Завершён',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger' | 'neutral'> = {
  active: 'success',
  paused: 'neutral',
  'over-quota': 'danger',
  completed: 'neutral',
};

const ALL_STATUSES = Array.from(new Set(PROJECTS.map((p) => p.status))) as ProjectStatus[];
const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const filteredProjects = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses],
  );

  const pageCount = Math.max(1, Math.ceil(filteredProjects.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const pageItems = filteredProjects.slice(
    (currentPage - 1) * PAGE_SIZE,
    currentPage * PAGE_SIZE,
  );

  const handleRemoveStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) => prev.filter((s) => s !== status));
    setPage(1);
  };

  const handleResetFilters = () => {
    setActiveStatuses(ALL_STATUSES);
    setPage(1);
  };

  return (
    <section style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-5)' }}>
      <div
        role="group"
        aria-label="Фильтры по статусу проекта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-space-2)' }}
      >
        {activeStatuses.length > 0 ? (
          activeStatuses.map((status) => (
            <JxChip key={status} tone={STATUS_TONE[status]} onRemove={() => handleRemoveStatus(status)}>
              {STATUS_LABEL[status]}
            </JxChip>
          ))
        ) : (
          <span style={{ color: 'var(--jx-color-text-muted)', fontSize: 'var(--jx-font-size-sm)' }}>
            Все фильтры сняты
          </span>
        )}
      </div>

      {filteredProjects.length === 0 ? (
        <JxEmptyState
          title="Нет проектов по выбранным фильтрам"
          description="Снимите или сбросьте фильтры по статусу, чтобы увидеть расход по проектам."
          action={
            <JxButton variant="primary" onClick={handleResetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-5)' }}>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>
            {pageItems.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 'var(--jx-space-4)',
                  padding: 'var(--jx-space-3) 0',
                  borderBottom: '1px solid var(--jx-color-border-subtle)',
                }}
              >
                <span style={{ fontWeight: 'var(--jx-font-weight-medium)' }}>{project.name}</span>
                <div style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-4)' }}>
                  <JxCircularProgress
                    value={Math.min(project.quotaPercent, 100)}
                    max={100}
                    size="sm"
                    label={`${project.quotaPercent}%`}
                    aria-label={`Заполненность квоты: ${project.quotaPercent}%`}
                  />
                  <JxBadge tone={STATUS_TONE[project.status]}>{STATUS_LABEL[project.status]}</JxBadge>
                </div>
              </li>
            ))}
          </ul>

          {pageCount > 1 && (
            <JxPagination
              page={currentPage}
              pageCount={pageCount}
              onPageChange={setPage}
              aria-label="Страницы списка проектов"
            />
          )}
        </div>
      )}
    </section>
  );
}

